// spec: .qa/e2e/specs/devices.md (2.2) · case: .qa/tests/devices/DEV-008.md
// seed: tests/seed.user.spec.ts (сессия user.json — из профиля Mac devA, без нового входа: лимит устройств 2/2)
// Только просмотр. НИКОГДА не нажимать «הסרה», «שמירה», не переключать роли.
import { test, expect, type Route } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

const ERROR_TITLE = 'משהו השתבש';
const ERROR_TEXT = 'לא הצלחנו לטעון את המידע. בדקו את החיבור ונסו שוב.';
const LIST_TITLE = 'הטלפונים בחשבון';
const ERROR_DEADLINE_MS = 15_000; // было ~55–60 с (#0af24eb7), после исправления ~7 с

// «Нет сети» (только веб): все запросы к серверу данных Supabase обрываются как при отключённом интернете,
// кроме профиля пользователя — он в ручной проверке 14.10 уже был загружен приложением на экране «חשבון» (кэш).
// Файлы самого приложения (JS) не трогаем — как при подмене window.fetch на iPhone 14.10.
// Почему не переход «חשבון» → «מכשירים»: у сессии devA (главное устройство) список телефонов уже загружен на «חשבון»
// и без сети показывается из кэша — экрана ошибки нет. Поэтому экран открывается заново, без списка в кэше.
const isBackend = (u: URL) => u.hostname.endsWith('.supabase.co') && !u.pathname.endsWith('/rest/v1/profiles');
const offline = (r: Route) => r.abort('internetdisconnected');

test.describe('«מכשירים» — ошибка загрузки и «נסו שוב»', () => {
  test('Без сети «מכשירים» быстро (≤ 15 с) показывает «משהו השתבש» с «נסו שוב», после восстановления сети — список «הטלפונים בחשבון» #0af24eb7 @iphone @prod-safe', async ({ page }) => {
    // 1. Вход есть, данные аккаунта загружены (экран «חשבון»)
    await page.goto('/account');
    await expect(page.getByText('מכשירים', { exact: true }).filter({ visible: true }).last(), 'сессия user.json недействительна — обновить из профиля devA').toBeVisible();
    await expect(page.getByRole('progressbar').filter({ visible: true })).toHaveCount(0);

    // 2. Сеть пропала → открыть «מכשירים»
    await page.route(isBackend, offline);
    const started = Date.now();
    await page.goto('/account/devices', { waitUntil: 'domcontentloaded' });
    await expect(page.getByRole('heading', { name: 'מכשירים' })).toBeVisible();

    // 3. Ошибка появляется не позже 15 с (источник: «מה רצוי» #0af24eb7, комментарий программиста — ~7 с)
    await expect(page.getByText(ERROR_TEXT).filter({ visible: true })).toBeVisible({ timeout: ERROR_DEADLINE_MS });
    const elapsed = Date.now() - started;
    test.info().annotations.push({ type: 'error-after-ms', description: String(elapsed) });
    expect(elapsed, 'ошибка без сети должна появиться ≤ 15 с').toBeLessThanOrEqual(ERROR_DEADLINE_MS);
    await expect(page.getByText(ERROR_TITLE, { exact: true }).filter({ visible: true })).toBeVisible();
    const retry = page.getByRole('button', { name: 'נסו שוב' }).filter({ visible: true });
    await expect(retry).toBeVisible();
    await expect(page.getByText(LIST_TITLE).filter({ visible: true })).toHaveCount(0);
    await expect(page.getByText(/^טוען/).filter({ visible: true })).toHaveCount(0);

    // 4. Сеть вернулась → «נסו שוב» → список телефонов
    await page.unroute(isBackend, offline);
    const retried = Date.now();
    await retry.click();
    await expect(page.getByText(LIST_TITLE).filter({ visible: true })).toBeVisible({ timeout: 30_000 });
    test.info().annotations.push({ type: 'list-after-retry-ms', description: String(Date.now() - retried) });
    await expect(page.getByRole('button', { name: /, מחובר$/ }).filter({ visible: true }).first()).toBeVisible();
    await expect(page.getByText(ERROR_TEXT).filter({ visible: true })).toHaveCount(0);
    await expect(page.getByRole('button', { name: 'נסו שוב' }).filter({ visible: true })).toHaveCount(0);
  });
});
